    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    rich_aggressive = 0
    desperate_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0)
                prev_bids.append(b)
                if b >= 90 and opp.get('budget', 0) >= 90:
                    rich_aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    slots = int(supply // WATER_REQ)
    if slots < 1:
        slots = 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = 0.0
    if len(prev_bids) >= 2:
        sorted_bids = sorted(prev_bids, reverse=True)
        second_prev = sorted_bids[int(1)]

    urgent = hp <= 3 or no_water >= 1
    critical = hp <= 2 or no_water >= 2
    late_game = day >= 8

    if slots >= 2:
        base = 24.0
        if desperate_count >= 2:
            base = 38.0
        if urgent:
            base = max(base, 52.0)
        if critical:
            base = max(base, 82.0)
        if rich_aggressive >= 2 and not urgent:
            base = min(base, 20.0)
        bid = base
    else:
        anchor = highest_prev
        if second_prev > 0:
            anchor = max(anchor, second_prev + 2.0)
        bid = max(58.0, min(anchor + 3.0, 108.0))
        if urgent:
            bid = max(bid, 88.0)
        if critical:
            bid = max(bid, 112.0)
        if late_game and hp >= 5 and no_water == 0:
            bid = min(bid, 72.0)

    if highest_prev >= 120 and not urgent and slots >= 2:
        bid = min(bid, 18.0)

    if budget < bid:
        if urgent:
            bid = budget
        else:
            bid = min(budget, max(0.0, bid * 0.75))

    reserve_floor = 0.0
    if not critical:
        reserve_floor = max(0.0, budget - DAILY_SALARY * 3)
        bid = min(bid, max(18.0 if slots >= 2 else 45.0, budget - reserve_floor))

    if urgent and budget >= 85:
        bid = max(bid, 85.0 if slots >= 2 else 98.0)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If we are nearly out of water/HP, we must bid aggressively.
    must_win = (hp <= 2) or (no_water_days >= 2)

    # Read yesterday bids to infer their aggressiveness.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Base aggressiveness from yesterday.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / max(1, len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # Supply pressure: with higher supply, we can bid slightly less.
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_norm < 0.0:
        supply_norm = 0.0
    if supply_norm > 1.0:
        supply_norm = 1.0

    # Target bid bands.
    # Surviving opponents bid around ~97 yesterday; we try to be competitive but cheaper.
    # If they were bidding very high, increase.
    if must_win:
        target = DAILY_SALARY * (0.85 - 0.15 * supply_norm)  # 76.5..85.5
    else:
        # If their highest bid is high, we shadow slightly below it.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = min(DAILY_SALARY * (0.75 - 0.10 * supply_norm), highest_prev_bid - 2.0)
        else:
            # Otherwise, bid around the average/typical survival level.
            base = max(DAILY_SALARY * (0.55 - 0.05 * supply_norm), avg_prev_bid * 0.9)
            target = base

    # Convert target into a budget-safe bid.
    # Never bid more than we can afford.
    bid = min(budget, max(1.0, target))

    # If budget is low, cap more tightly to avoid early bankruptcy.
    if budget < DAILY_SALARY * 0.6:
        bid = min(bid, budget * 0.9)

    # Small late-episode escalation (day 8-10) to secure remaining survival.
    if day >= 8:
        bid = min(budget, bid * 1.08)

    return float(bid)

